root = os.path.expanduser(sys.argv[1] if len(sys.argv) > 1 else '~/baja-apps')
h = lambda t: hashlib.sha256(t.replace('\r\n', '\n').encode()).hexdigest()
todo = []
for rel in NEW:
    p = os.path.join(root, rel)
    if not os.path.isfile(p):
        sys.exit('Not found: ' + p + '. Nothing was changed.')
    cur = h(open(p, encoding='utf-8').read())
    if cur == h(NEW[rel]):
        print('Already installed:', p)
    elif cur == BASE[rel]:
        todo.append((rel, p))
    else:
        sys.exit(p + ' differs from the version this update was made against. Nothing was changed.')
for rel, p in todo:
    shutil.copyfile(p, p + '.before-competition')
    open(p, 'w', encoding='utf-8').write(NEW[rel])
    print('Updated', p)
print('Restart baja-server (it caches scripts), then hard-refresh the editor (Ctrl+Shift+R).')
